package dk.zlatan.flotmand.Features.frontpage.model
import com.google.firebase.auth.FirebaseUser
data class User( val uid: String? = null, val email: String? = null, val displayName: String? = null, val photoUrl: String? = null, val profilePicture: Int? = null, // For local resource fallback val name: String? = null // For local fallback or custom name ) { // Optional: secondary constructor for FirebaseUser constructor(firebaseUser: FirebaseUser?) : this( uid = firebaseUser?.uid, email = firebaseUser?.email, displayName = firebaseUser?.displayName, photoUrl = firebaseUser?.photoUrl?.toString(), profilePicture = null, name = firebaseUser?.displayName ) }

